package app

import (
	"sync"

	"fyne.io/fyne/v2"
)

var (
	metaLock sync.RWMutex
	appMeta  = fyne.AppMetadata{
		ID:      "com.example",
		Name:    "Fyne App",
		Version: "1.0.0",
		Build:   1,
	}
)

// SetMetadata allows an application to override the default metadata at runtime.
// This should typically be called early in the application lifecycle, before any
// calls to Metadata().
//
// Since: 2.2
func SetMetadata(meta fyne.AppMetadata) {
	metaLock.Lock()
	defer metaLock.Unlock()
	appMeta = meta
}

func getMetadata() fyne.AppMetadata {
	metaLock.RLock()
	defer metaLock.RUnlock()
	return appMeta
}

package app

import (
	"sync"

	"fyne.io/fyne/v2"
)

var (
